//! Integration tests for concurrent search on a shared `TurboQuantIndex`.
//!
//! These tests exercise the `OnceLock`-based lazy cache initialisation
//! introduced to let `search` take `&self`. They verify that:
//!
//! 1. A shared `Arc<TurboQuantIndex>` can serve searches from many
//!    threads concurrently without external locking.
//! 2. Every concurrent thread that searches the same query against a
//!    shared index gets the same top-`k` back.
//! 3. `prepare()` is safe to call from multiple threads.
//! 4. A roundtrip through `write`/`load` produces the same top-`k` as
//!    the original in-memory index for the same queries.

use std::sync::Arc;
use std::thread;

use turbovec::TurboQuantIndex;

/// Deterministic pseudo-random vector generator so the tests are
/// reproducible without pulling an extra dev-dependency.
fn make_vectors(n: usize, dim: usize, seed: u64) -> Vec<f32> {
    let mut state = seed.wrapping_mul(0x9E3779B97F4A7C15);
    let mut out = Vec::with_capacity(n * dim);
    for _ in 0..(n * dim) {
        state = state
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        let u = ((state >> 32) as u32) as f32 / u32::MAX as f32;
        // Centre on zero and scale modestly so rotation has room to move things.
        out.push(u * 2.0 - 1.0);
    }
    out
}

/// Build a small index ready for concurrent search.
fn build_index() -> TurboQuantIndex {
    let dim = 256;
    let bit_width = 4;
    let n = 1_024;

    let vectors = make_vectors(n, dim, 1);
    let mut index = TurboQuantIndex::new(dim, bit_width).unwrap();
    index.add(&vectors);
    assert_eq!(index.len(), n);
    index
}

#[test]
fn search_is_deterministic_across_threads() {
    let index = Arc::new(build_index());

    // Warm up explicitly so no thread races on the lazy init path.
    index.prepare();

    let queries = make_vectors(4, index.dim(), 42);
    let k = 10;

    // Reference result from the main thread.
    let reference = index.search(&queries, k);
    let ref_indices: Vec<Vec<i64>> = (0..reference.nq)
        .map(|qi| reference.indices_for_query(qi).to_vec())
        .collect();
    let nq = reference.nq;

    // Every spawned thread should see the same indices for the same
    // queries — OnceLock caches must be visible to all readers.
    let mut handles = Vec::new();
    for _ in 0..16 {
        let index = Arc::clone(&index);
        let queries = queries.clone();
        let ref_indices = ref_indices.clone();
        handles.push(thread::spawn(move || {
            for _ in 0..32 {
                let result = index.search(&queries, k);
                assert_eq!(result.nq, nq);
                assert_eq!(result.k, k);
                for (qi, expected) in ref_indices.iter().enumerate() {
                    assert_eq!(
                        result.indices_for_query(qi),
                        expected.as_slice(),
                        "top-k mismatch between threads for query {qi}"
                    );
                }
            }
        }));
    }
    for h in handles {
        h.join().expect("search thread panicked");
    }
}

#[test]
fn lazy_init_is_safe_when_prepare_is_skipped() {
    // Deliberately do NOT call `prepare()` — the first concurrent
    // batch races through `get_or_init`, and OnceLock must let exactly
    // one thread initialise each cache while the others block briefly
    // then read the shared value.
    let index = Arc::new(build_index());
    let queries = make_vectors(2, index.dim(), 7);
    let k = 5;

    let mut handles = Vec::new();
    for _ in 0..32 {
        let index = Arc::clone(&index);
        let queries = queries.clone();
        handles.push(thread::spawn(move || {
            let r = index.search(&queries, k);
            // The only thing we can assert without a reference value
            // is that every call returns `nq * k` indices and no panic.
            assert_eq!(r.indices.len(), r.nq * r.k);
            assert_eq!(r.scores.len(), r.nq * r.k);
        }));
    }
    for h in handles {
        h.join().expect("search thread panicked");
    }
}

#[test]
fn prepare_is_idempotent_from_multiple_threads() {
    let index = Arc::new(build_index());

    let mut handles = Vec::new();
    for _ in 0..8 {
        let index = Arc::clone(&index);
        handles.push(thread::spawn(move || {
            index.prepare();
            index.prepare();
        }));
    }
    for h in handles {
        h.join().expect("prepare thread panicked");
    }

    // The index must still be usable afterwards.
    let queries = make_vectors(1, index.dim(), 99);
    let r = index.search(&queries, 3);
    assert_eq!(r.k, 3);
}

#[test]
fn add_after_search_invalidates_blocked_cache() {
    // The `add` method must reset the `blocked` OnceLock so the next
    // search sees the extended vector set. If we forgot to invalidate,
    // the search would still score against the pre-`add` packed codes.
    let mut index = build_index();
    let queries = make_vectors(1, index.dim(), 3);
    let _before = index.search(&queries, 5);

    // Add 512 more vectors — roughly doubling the index.
    let more = make_vectors(512, index.dim(), 11);
    index.add(&more);
    assert_eq!(index.len(), 1_024 + 512);

    // The top-5 after `add` must come from an index of `len() = 1536`.
    // The only invariant we can check cheaply is that every returned
    // position is in-range for the new size.
    let after = index.search(&queries, 5);
    for &idx in after.indices_for_query(0) {
        assert!(idx >= 0, "negative index");
        assert!((idx as usize) < index.len(), "stale index out of range");
    }
}

#[test]
fn write_load_preserves_concurrent_search_results() {
    let index = build_index();
    let queries = make_vectors(3, index.dim(), 123);
    let k = 8;

    let before = index.search(&queries, k);

    let tmp = std::env::temp_dir().join(format!("turbovec_concurrent_{}.tv", std::process::id()));
    index.write(&tmp).expect("write");
    let reloaded = TurboQuantIndex::load(&tmp).expect("load");
    let _ = std::fs::remove_file(&tmp);

    assert_eq!(reloaded.len(), index.len());
    assert_eq!(reloaded.dim(), index.dim());
    assert_eq!(reloaded.bit_width(), index.bit_width());

    // The reloaded index must produce the same top-k for the same
    // queries because rotation and centroids are deterministic
    // functions of `(dim, seed)` and `(bit_width, dim)`.
    let after = reloaded.search(&queries, k);
    for qi in 0..before.nq {
        assert_eq!(
            before.indices_for_query(qi),
            after.indices_for_query(qi),
            "roundtrip changed top-k for query {qi}"
        );
    }
}

//! Correctness tests for Lloyd-Max codebook generation.
//!
//! After orthogonal rotation, each coordinate of a unit vector on the
//! sphere S^{d-1} follows Beta((d-1)/2, (d-1)/2) on [-1, 1]. The
//! Lloyd-Max iteration produces the MMSE scalar quantizer for that
//! distribution. These tests verify structural invariants at
//! representative (bits, dim) pairs that the encoding pipeline relies
//! on.

use turbovec::codebook::codebook;

#[test]
fn centroids_strictly_ascending() {
    for &bits in &[2usize, 3, 4] {
        for &dim in &[256usize, 768, 1536] {
            let (_, centroids) = codebook(bits, dim);
            for i in 0..centroids.len() - 1 {
                assert!(
                    centroids[i] < centroids[i + 1],
                    "centroids not ascending at bits={}, dim={}: c[{}]={} >= c[{}]={}",
                    bits,
                    dim,
                    i,
                    centroids[i],
                    i + 1,
                    centroids[i + 1]
                );
            }
        }
    }
}

#[test]
fn boundaries_strictly_between_centroids() {
    for &bits in &[2usize, 3, 4] {
        for &dim in &[256usize, 1536] {
            let (boundaries, centroids) = codebook(bits, dim);
            assert_eq!(boundaries.len(), centroids.len() - 1);
            for i in 0..boundaries.len() {
                assert!(
                    boundaries[i] > centroids[i],
                    "boundary[{}] = {} not > centroid[{}] = {} (bits={}, dim={})",
                    i,
                    boundaries[i],
                    i,
                    centroids[i],
                    bits,
                    dim
                );
                assert!(
                    boundaries[i] < centroids[i + 1],
                    "boundary[{}] = {} not < centroid[{}] = {} (bits={}, dim={})",
                    i,
                    boundaries[i],
                    i + 1,
                    centroids[i + 1],
                    bits,
                    dim
                );
            }
        }
    }
}

#[test]
fn level_counts_correct() {
    for &bits in &[2usize, 3, 4] {
        let (boundaries, centroids) = codebook(bits, 1536);
        assert_eq!(
            centroids.len(),
            1 << bits,
            "expected 2^{} = {} centroids, got {}",
            bits,
            1 << bits,
            centroids.len()
        );
        assert_eq!(
            boundaries.len(),
            (1 << bits) - 1,
            "expected 2^{} - 1 = {} boundaries, got {}",
            bits,
            (1 << bits) - 1,
            boundaries.len()
        );
    }
}

#[test]
fn symmetric_about_zero() {
    for &bits in &[2usize, 3, 4] {
        for &dim in &[768usize, 1536] {
            let (_, centroids) = codebook(bits, dim);
            let n = centroids.len();
            for i in 0..n / 2 {
                let lo = centroids[i];
                let hi = centroids[n - 1 - i];
                assert!(
                    (lo + hi).abs() < 1e-4,
                    "asymmetric: c[{}]={} c[{}]={} (bits={}, dim={})",
                    i,
                    lo,
                    n - 1 - i,
                    hi,
                    bits,
                    dim
                );
            }
        }
    }
}

#[test]
fn deterministic_for_same_params() {
    let (b1, c1) = codebook(4, 1536);
    let (b2, c2) = codebook(4, 1536);
    assert_eq!(b1, b2);
    assert_eq!(c1, c2);
}

#[test]
fn centroids_within_unit_interval() {
    for &bits in &[2usize, 3, 4] {
        let (_, centroids) = codebook(bits, 1536);
        for (i, &c) in centroids.iter().enumerate() {
            assert!(
                c > -1.0 && c < 1.0,
                "centroid[{}] = {} outside (-1, 1) (bits={})",
                i,
                c,
                bits
            );
        }
    }
}

//! Correctness tests for `IdMapIndex` — the stable-id wrapper.
//!
//! Invariants exercised:
//!   - `add_with_ids` returns `Err` on bad input (length mismatch, duplicate id).
//!   - `remove` returns true/false and keeps `len` consistent.
//!   - After `remove`, search doesn't return the removed id, and every
//!     remaining id still self-queries to itself.
//!   - Remove then re-add with the same id works.
//!   - Internal `slot_to_id` / `id_to_slot` tables stay consistent after
//!     a swap-and-pop (verified indirectly via search correctness).

use turbovec::IdMapIndex;

fn gaussian_normalized(n: usize, dim: usize, seed: u64) -> Vec<f32> {
    let mut state = seed | 1;
    let mut next = || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    let mut uniform = || {
        let raw = (next() >> 40) as u32 | 1;
        raw as f32 / (1u32 << 24) as f32
    };
    let two_pi = 2.0_f32 * std::f32::consts::PI;
    let mut data = vec![0.0f32; n * dim];
    let mut i = 0;
    while i < data.len() {
        let u1 = uniform().max(1e-7);
        let u2 = uniform();
        let r = (-2.0 * u1.ln()).sqrt();
        let theta = two_pi * u2;
        data[i] = r * theta.cos();
        if i + 1 < data.len() {
            data[i + 1] = r * theta.sin();
        }
        i += 2;
    }
    for row_i in 0..n {
        let row = &mut data[row_i * dim..(row_i + 1) * dim];
        let norm: f32 = row.iter().map(|x| x * x).sum::<f32>().sqrt();
        if norm > 0.0 {
            let inv = 1.0 / norm;
            for x in row.iter_mut() {
                *x *= inv;
            }
        }
    }
    data
}

#[test]
fn add_with_ids_updates_len_and_contains() {
    let dim = 128;
    let data = gaussian_normalized(5, dim, 0xA11D_0000);
    let mut idx = IdMapIndex::new(dim, 4).unwrap();
    idx.add_with_ids(&data, &[100, 200, 300, 400, 500]).unwrap();

    assert_eq!(idx.len(), 5);
    assert!(idx.contains(300));
    assert!(!idx.contains(999));
}

#[test]
fn search_returns_ids_not_slots() {
    let dim = 256;
    let data = gaussian_normalized(10, dim, 0xA11D_0001);
    let mut idx = IdMapIndex::new(dim, 4).unwrap();
    let ids: Vec<u64> = (1_000_000..1_000_010).collect();
    idx.add_with_ids(&data, &ids).unwrap();

    // Self-query each vector: expect the matching external id as top-1.
    for (i, &expected_id) in ids.iter().enumerate() {
        let q = &data[i * dim..(i + 1) * dim];
        let (_, got_ids) = idx.search(q, 1);
        assert_eq!(got_ids[0], expected_id);
    }
}

#[test]
fn remove_returns_false_for_missing_id() {
    let dim = 128;
    let data = gaussian_normalized(3, dim, 0xA11D_0002);
    let mut idx = IdMapIndex::new(dim, 4).unwrap();
    idx.add_with_ids(&data, &[1, 2, 3]).unwrap();

    assert!(!idx.remove(999));
    assert_eq!(idx.len(), 3);
}

#[test]
fn remove_existing_id_shrinks_and_hides_it() {
    let dim = 256;
    let data = gaussian_normalized(10, dim, 0xA11D_0003);
    let mut idx = IdMapIndex::new(dim, 4).unwrap();
    let ids: Vec<u64> = (0..10).map(|i| i as u64 * 7 + 11).collect();
    idx.add_with_ids(&data, &ids).unwrap();

    // Remove the third vector (id = 25, at slot 2).
    let target_id = ids[2];
    assert!(idx.remove(target_id));
    assert_eq!(idx.len(), 9);
    assert!(!idx.contains(target_id));

    // Its own vector should no longer be returned as a top-1 under its id.
    let q = &data[2 * dim..3 * dim];
    let (_, got_ids) = idx.search(q, 9);
    assert!(!got_ids.contains(&target_id));
}

#[test]
fn remaining_ids_still_self_query_after_mixed_removes() {
    let dim = 384;
    let data = gaussian_normalized(20, dim, 0xA11D_0004);
    let mut idx = IdMapIndex::new(dim, 4).unwrap();
    let ids: Vec<u64> = (0..20).map(|i| i as u64 * 100 + 5).collect();
    idx.add_with_ids(&data, &ids).unwrap();

    // Remove a few ids in different orders — some will trigger
    // swap-and-pop, some will be the last vector (no swap).
    idx.remove(ids[7]);   // middle
    idx.remove(ids[19]);  // last
    idx.remove(ids[0]);   // first

    assert_eq!(idx.len(), 17);
    assert!(!idx.contains(ids[7]));
    assert!(!idx.contains(ids[19]));
    assert!(!idx.contains(ids[0]));

    // Every surviving id still maps back to its own vector.
    for (i, &id) in ids.iter().enumerate() {
        if i == 0 || i == 7 || i == 19 {
            continue;
        }
        let q = &data[i * dim..(i + 1) * dim];
        let (_, got_ids) = idx.search(q, 1);
        assert_eq!(
            got_ids[0], id,
            "id {id} (row {i}) no longer self-queries correctly after remove",
        );
    }
}

#[test]
fn remove_then_re_add_same_id_is_allowed() {
    let dim = 128;
    let data = gaussian_normalized(5, dim, 0xA11D_0005);
    let mut idx = IdMapIndex::new(dim, 4).unwrap();
    idx.add_with_ids(&data, &[1, 2, 3, 4, 5]).unwrap();

    assert!(idx.remove(3));
    assert!(!idx.contains(3));

    // Re-add a new vector with id 3.
    let new_vec = gaussian_normalized(1, dim, 0xA11D_BEEF);
    idx.add_with_ids(&new_vec, &[3]).unwrap();
    assert!(idx.contains(3));
    assert_eq!(idx.len(), 5);
}

#[test]
fn add_with_ids_rejects_duplicate_id() {
    let dim = 128;
    let data = gaussian_normalized(5, dim, 0xA11D_0006);
    let mut idx = IdMapIndex::new(dim, 4).unwrap();
    idx.add_with_ids(&data[..2 * dim], &[1, 2]).unwrap();
    // Same id "2" already present.
    let err = idx
        .add_with_ids(&data[2 * dim..3 * dim], &[2])
        .unwrap_err();
    assert_eq!(err, turbovec::AddError::IdAlreadyPresent(2));
}

#[test]
fn add_with_ids_rejects_length_mismatch() {
    let dim = 128;
    let data = gaussian_normalized(5, dim, 0xA11D_0007);
    let mut idx = IdMapIndex::new(dim, 4).unwrap();
    // 5 vectors, only 3 ids.
    let err = idx.add_with_ids(&data, &[1, 2, 3]).unwrap_err();
    assert_eq!(
        err,
        turbovec::AddError::IdsCountMismatch {
            expected: 5,
            got: 3,
        },
    );
}

#[test]
fn write_and_load_round_trips() {
    let dim = 256;
    let data = gaussian_normalized(10, dim, 0xA11D_0100);
    let ids: Vec<u64> = (2000..2010).collect();

    let mut idx = IdMapIndex::new(dim, 4).unwrap();
    idx.add_with_ids(&data, &ids).unwrap();

    // Delete a few to exercise non-identity slot_to_id mapping.
    idx.remove(2003);
    idx.remove(2007);

    let tmp = std::env::temp_dir().join(format!("turbovec_idmap_{}.tvim", std::process::id()));
    idx.write(&tmp).expect("write failed");

    let restored = IdMapIndex::load(&tmp).expect("load failed");
    assert_eq!(restored.len(), 8);
    assert!(restored.contains(2000));
    assert!(!restored.contains(2003));
    assert!(!restored.contains(2007));

    // Every surviving id should still self-query to itself on the
    // restored index (exercising packed_codes + scales + slot_to_id
    // all round-trip correctly).
    for (i, &id) in ids.iter().enumerate() {
        if id == 2003 || id == 2007 {
            continue;
        }
        let q = &data[i * dim..(i + 1) * dim];
        let (_, got_ids) = restored.search(q, 1);
        assert_eq!(got_ids[0], id, "id {id} failed to self-query after reload");
    }

    std::fs::remove_file(&tmp).ok();
}

#[test]
fn load_rejects_wrong_magic() {
    let tmp = std::env::temp_dir().join(format!(
        "turbovec_idmap_badmagic_{}.tvim",
        std::process::id()
    ));
    // Write a file that starts with the `.tv` format instead of `TVIM`.
    let dim = 64;
    let data = gaussian_normalized(2, dim, 0xA11D_0101);
    let mut inner = IdMapIndex::new(dim, 4).unwrap();
    inner.add_with_ids(&data, &[1, 2]).unwrap();
    // Use the inner TurboQuantIndex's write to produce a .tv file.
    // We can't do that directly since inner is private; simulate with
    // arbitrary bytes of the right shape.
    std::fs::write(&tmp, b"XXXX\x01").expect("write junk");
    let res = IdMapIndex::load(&tmp);
    assert!(res.is_err(), "load should reject file without TVIM magic");
    std::fs::remove_file(&tmp).ok();
}

#[test]
fn empty_index_round_trip() {
    let dim = 128;
    let idx = IdMapIndex::new(dim, 4).unwrap();

    let tmp = std::env::temp_dir().join(format!(
        "turbovec_idmap_empty_{}.tvim",
        std::process::id()
    ));
    idx.write(&tmp).expect("write failed");

    let restored = IdMapIndex::load(&tmp).expect("load failed");
    assert_eq!(restored.len(), 0);
    assert_eq!(restored.dim(), dim);
    assert_eq!(restored.bit_width(), 4);
    std::fs::remove_file(&tmp).ok();
}

//! Correctness of `TurboQuantIndex::swap_remove`.
//!
//! Invariants tested at the behaviour level (no private-state access):
//!   - `len()` decreases by one; return value is the position of the
//!     vector that moved into the deleted slot.
//!   - The deleted vector no longer appears as a self-query top-1.
//!   - Every non-deleted vector still self-queries to itself.
//!   - Deleting the last vector is a no-op swap (return == idx).
//!   - Out-of-bounds delete panics.
//!   - Cache invalidation: a search immediately after a delete reflects
//!     the new layout (no stale `OnceLock` blocked cache).

use turbovec::TurboQuantIndex;

fn gaussian_normalized(n: usize, dim: usize, seed: u64) -> Vec<f32> {
    let mut state = seed | 1;
    let mut next = || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    let mut uniform = || {
        let raw = (next() >> 40) as u32 | 1;
        raw as f32 / (1u32 << 24) as f32
    };
    let two_pi = 2.0_f32 * std::f32::consts::PI;
    let mut data = vec![0.0f32; n * dim];
    let mut i = 0;
    while i < data.len() {
        let u1 = uniform().max(1e-7);
        let u2 = uniform();
        let r = (-2.0 * u1.ln()).sqrt();
        let theta = two_pi * u2;
        data[i] = r * theta.cos();
        if i + 1 < data.len() {
            data[i + 1] = r * theta.sin();
        }
        i += 2;
    }
    for row_i in 0..n {
        let row = &mut data[row_i * dim..(row_i + 1) * dim];
        let norm: f32 = row.iter().map(|x| x * x).sum::<f32>().sqrt();
        if norm > 0.0 {
            let inv = 1.0 / norm;
            for x in row.iter_mut() {
                *x *= inv;
            }
        }
    }
    data
}

#[test]
fn swap_remove_shrinks_length_and_returns_last_index() {
    let dim = 256;
    let data = gaussian_normalized(10, dim, 0xDE1E_7E00);
    let mut idx = TurboQuantIndex::new(dim, 4).unwrap();
    idx.add(&data);
    assert_eq!(idx.len(), 10);

    let moved_from = idx.swap_remove(3);
    assert_eq!(moved_from, 9);
    assert_eq!(idx.len(), 9);
}

#[test]
fn swap_remove_last_is_no_swap() {
    let dim = 256;
    let data = gaussian_normalized(5, dim, 0xDE1E_7E01);
    let mut idx = TurboQuantIndex::new(dim, 4).unwrap();
    idx.add(&data);

    // Removing the last element: moved_from == idx, no actual swap.
    let moved_from = idx.swap_remove(4);
    assert_eq!(moved_from, 4);
    assert_eq!(idx.len(), 4);
}

#[test]
fn search_after_swap_remove_reflects_new_layout() {
    // Cache-invalidation regression test: the OnceLock blocked cache
    // must be reset when swap_remove runs, otherwise search returns
    // scores against stale packed codes.
    let dim = 512;
    let n = 100;
    let data = gaussian_normalized(n, dim, 0xDE1E_7E02);

    let mut idx = TurboQuantIndex::new(dim, 4).unwrap();
    idx.add(&data);

    // Prime the cache with a self-query.
    let q = &data[5 * dim..6 * dim];
    let res = idx.search(q, 1);
    assert_eq!(res.indices_for_query(0)[0], 5);

    // Delete vector 5. The vector at position (n-1)=99 moves into slot 5.
    let moved_from = idx.swap_remove(5);
    assert_eq!(moved_from, n - 1);
    assert_eq!(idx.len(), n - 1);

    // Self-query on the vector that USED to be at index 99: now expect
    // top-1 to come back as index 5 (the slot it moved into). This
    // requires the cache to have been rebuilt.
    let q_moved = &data[(n - 1) * dim..n * dim];
    let res = idx.search(q_moved, 1);
    assert_eq!(
        res.indices_for_query(0)[0],
        5,
        "cache invalidation failure: moved vector not found at its new slot"
    );
}

#[test]
fn deleted_vector_no_longer_returned() {
    let dim = 512;
    let n = 64;
    let data = gaussian_normalized(n, dim, 0xDE1E_7E03);

    let mut idx = TurboQuantIndex::new(dim, 4).unwrap();
    idx.add(&data);

    // Remove vector 7. Query with it: top-1 must NOT be 7 (that slot
    // now holds what was vector 63).
    idx.swap_remove(7);
    let q = &data[7 * dim..8 * dim];
    let res = idx.search(q, idx.len());
    let indices = res.indices_for_query(0);
    assert_eq!(indices.len(), idx.len());
    assert!(
        !indices.contains(&7i64)
            || indices[0] != 7i64,
        "deleted vector appears as top-1 after swap_remove"
    );
}

#[test]
fn remaining_vectors_still_self_query_correctly() {
    // After deleting a few, every remaining vector must still find
    // itself as top-1.
    let dim = 384;
    let n = 80;
    let data = gaussian_normalized(n, dim, 0xDE1E_7E04);

    let mut idx = TurboQuantIndex::new(dim, 4).unwrap();
    idx.add(&data);

    // Delete a handful of non-adjacent positions.
    // After each delete, len shrinks and the last slot's vector moves
    // into the deleted position. Track which original index lives
    // at each current slot.
    let mut live_at_slot: Vec<usize> = (0..n).collect();

    for &to_delete in &[10usize, 5, 40, 0] {
        let last = live_at_slot.len() - 1;
        let _moved = idx.swap_remove(to_delete);
        // Mirror the index's semantics in our tracker.
        live_at_slot.swap(to_delete, last);
        live_at_slot.pop();
    }

    // Now every slot should self-query back to its current slot.
    for (slot, &orig) in live_at_slot.iter().enumerate() {
        let q = &data[orig * dim..(orig + 1) * dim];
        let res = idx.search(q, 1);
        assert_eq!(
            res.indices_for_query(0)[0],
            slot as i64,
            "vector originally at {orig} (now slot {slot}) didn't self-query correctly"
        );
    }
}

#[test]
#[should_panic(expected = "out of bounds")]
fn swap_remove_out_of_bounds_panics() {
    let dim = 128;
    let data = gaussian_normalized(3, dim, 0xDE1E_7E05);
    let mut idx = TurboQuantIndex::new(dim, 4).unwrap();
    idx.add(&data);
    idx.swap_remove(3); // valid range is 0..3
}

//! End-to-end correctness tests for the encoding pipeline.
//!
//! `encode::encode` is the direct entry point for normalize ->
//! rotate -> quantize -> bit-pack -> compute correction scale.
//! Going through it (rather than through `TurboQuantIndex`) lets us
//! verify the low-level output shape and the per-vector scale value
//! without reaching into private state.

use turbovec::codebook::codebook;
use turbovec::encode::encode;
use turbovec::rotation::make_rotation_matrix;

fn make_vectors(n: usize, dim: usize, seed: u64) -> Vec<f32> {
    let mut state = seed.wrapping_mul(0x9E3779B97F4A7C15);
    let mut out = Vec::with_capacity(n * dim);
    for _ in 0..(n * dim) {
        state = state
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        let bits = (((state >> 32) as u32) & 0x007FFFFF) | 0x3F800000;
        let uniform = f32::from_bits(bits) - 1.0;
        out.push(uniform * 2.0 - 1.0);
    }
    out
}

#[test]
fn produces_expected_shape() {
    for &bit_width in &[2usize, 4] {
        let dim = 128;
        let n = 17;
        let rotation = make_rotation_matrix(dim);
        let (boundaries, centroids) = codebook(bit_width, dim);
        let vectors = make_vectors(n, dim, 0);

        let (packed, scales, _, _) = encode(
            &vectors, n, dim, &rotation, &boundaries, &centroids, bit_width, None,
        );

        let bytes_per_row = bit_width * (dim / 8);
        assert_eq!(
            packed.len(),
            n * bytes_per_row,
            "wrong packed length for bits={}, dim={}",
            bit_width,
            dim
        );
        assert_eq!(scales.len(), n);
    }
}

#[test]
fn scales_satisfy_rabitq_identity() {
    // Verify the mathematical identity that defines the correction:
    //     scale[i] = ||v_i|| / <u_i, x_hat_i>
    // where u_i is the rotated unit vector and x_hat_i is the
    // reconstructed-from-centroids vector. Both sides recoverable
    // here from the inputs.
    let dim = 128;
    let n = 10;
    let rotation = make_rotation_matrix(dim);
    let (boundaries, centroids) = codebook(4, dim);
    let vectors = make_vectors(n, dim, 0);

    let (_, scales, _, _) = encode(&vectors, n, dim, &rotation, &boundaries, &centroids, 4, None);

    // Reconstruct <u, x_hat> per vector and check scale = ||v|| / <u, x_hat>.
    for i in 0..n {
        let row = &vectors[i * dim..(i + 1) * dim];
        let norm: f32 = row.iter().map(|x| x * x).sum::<f32>().sqrt();
        let inv_norm = 1.0 / norm;

        // Rotate the unit vector: u_rot[k] = sum_j rotation[k*dim+j] * row[j] * inv_norm
        let mut u_rot = vec![0.0f32; dim];
        for k in 0..dim {
            let mut acc = 0.0f32;
            for j in 0..dim {
                acc += rotation[k * dim + j] * row[j] * inv_norm;
            }
            u_rot[k] = acc;
        }

        // Quantize each coord and look up centroid (x_hat values).
        let mut inner = 0.0f64;
        for k in 0..dim {
            let mut code: usize = 0;
            for &b in &boundaries {
                if u_rot[k] > b {
                    code += 1;
                }
            }
            inner += (u_rot[k] as f64) * (centroids[code] as f64);
        }
        let expected_scale = norm as f64 / inner.max(1e-10);

        let rel_err = (scales[i] as f64 - expected_scale).abs() / expected_scale.abs().max(1e-10);
        assert!(
            rel_err < 1e-4,
            "scale identity broken at i={}: stored={}, expected={}, rel_err={}",
            i,
            scales[i],
            expected_scale,
            rel_err,
        );
    }
}

#[test]
fn deterministic_output() {
    let dim = 128;
    let n = 5;
    let rotation = make_rotation_matrix(dim);
    let (boundaries, centroids) = codebook(4, dim);
    let vectors = make_vectors(n, dim, 0);

    let (p1, s1, _, _) = encode(&vectors, n, dim, &rotation, &boundaries, &centroids, 4, None);
    let (p2, s2, _, _) = encode(&vectors, n, dim, &rotation, &boundaries, &centroids, 4, None);

    assert_eq!(p1, p2);
    assert_eq!(s1, s2);
}

#[test]
fn handles_zero_vector() {
    // A zero-norm vector must not produce NaN codes or NaN scales.
    let dim = 128;
    let rotation = make_rotation_matrix(dim);
    let (boundaries, centroids) = codebook(4, dim);
    let zeros = vec![0.0f32; dim];

    let (packed, scales, _, _) = encode(&zeros, 1, dim, &rotation, &boundaries, &centroids, 4, None);

    // ||v|| = 0 => scale = 0 / <u, x_hat>_floor = 0
    assert_eq!(scales[0], 0.0);
    assert!(scales[0].is_finite());
    let bytes_per_row = 4 * (dim / 8);
    assert_eq!(packed.len(), bytes_per_row);
}

//! Format-versioning tests for `.tv` and `.tvim`.
//!
//! Verifies:
//! 1. Round-trip via the public write/load functions works on the current
//!    format (version 2) for both file types.
//! 2. A hand-constructed version-1 `.tv` file (bare bit_width-first
//!    header, no magic) is rejected with the upgrade-hint error.
//! 3. A hand-constructed version-1 `.tvim` file (TVIM magic with
//!    version byte 1) is rejected with the upgrade-hint error.

use std::fs::File;
use std::io::Write;
use std::path::PathBuf;

use turbovec::io::{load, load_id_map, write, write_id_map};

fn temp_path(name: &str) -> PathBuf {
    let mut p = std::env::temp_dir();
    let nonce = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .unwrap()
        .as_nanos();
    p.push(format!("turbovec-{}-{}", nonce, name));
    p
}

#[test]
fn tv_round_trip_current_format() {
    let path = temp_path("v2.tv");
    let bit_width = 4;
    let dim = 32;
    let n_vectors = 3;
    let packed = vec![0xABu8; (dim / 8) * bit_width * n_vectors];
    let scales = vec![1.5f32, 2.5, 3.5];

    // Round-trip with empty TQ+ calibration (identity); behaviour identical
    // to a v2 file otherwise. Separate test below covers populated calibration.
    write(&path, bit_width, dim, n_vectors, &packed, &scales, &[], &[]).unwrap();
    let (bw, d, n, p, s, shift, scale_tq) = load(&path).unwrap();

    assert_eq!(bw, bit_width);
    assert_eq!(d, dim);
    assert_eq!(n, n_vectors);
    assert_eq!(p, packed);
    assert_eq!(s, scales);
    assert!(shift.is_empty());
    assert!(scale_tq.is_empty());
    std::fs::remove_file(&path).ok();
}

#[test]
fn tv_round_trip_with_tqplus_calibration() {
    let path = temp_path("v3-tqplus.tv");
    let bit_width = 4;
    let dim = 32;
    let n_vectors = 3;
    let packed = vec![0xABu8; (dim / 8) * bit_width * n_vectors];
    let scales = vec![1.5f32, 2.5, 3.5];
    let shift: Vec<f32> = (0..dim).map(|d| d as f32 * 0.01).collect();
    let scale_tq: Vec<f32> = (0..dim).map(|d| 1.0 + d as f32 * 0.02).collect();

    write(&path, bit_width, dim, n_vectors, &packed, &scales, &shift, &scale_tq).unwrap();
    let (bw, d, n, p, s, loaded_shift, loaded_scale) = load(&path).unwrap();

    assert_eq!(bw, bit_width);
    assert_eq!(d, dim);
    assert_eq!(n, n_vectors);
    assert_eq!(p, packed);
    assert_eq!(s, scales);
    assert_eq!(loaded_shift, shift);
    assert_eq!(loaded_scale, scale_tq);
    std::fs::remove_file(&path).ok();
}

#[test]
fn tv_v1_file_is_rejected_with_upgrade_hint() {
    // Hand-construct a turbovec ≤ 0.4.3 `.tv` file: bare header
    // (bit_width=4, dim=32, n_vectors=2), packed codes, two f32 norms.
    let path = temp_path("v1.tv");
    {
        let mut f = File::create(&path).unwrap();
        f.write_all(&[4u8]).unwrap(); // bit_width
        f.write_all(&(32u32).to_le_bytes()).unwrap(); // dim
        f.write_all(&(2u32).to_le_bytes()).unwrap(); // n_vectors
        f.write_all(&vec![0u8; (32 / 8) * 4 * 2]).unwrap(); // packed codes
        f.write_all(&(1.0f32).to_le_bytes()).unwrap(); // norm 0
        f.write_all(&(2.0f32).to_le_bytes()).unwrap(); // norm 1
    }

    let err = load(&path).unwrap_err();
    let msg = err.to_string();
    assert!(
        msg.contains("turbovec ≤ 0.4.3") && msg.contains("Rebuild"),
        "expected upgrade hint, got: {}",
        msg
    );
    std::fs::remove_file(&path).ok();
}

#[test]
fn tvim_round_trip_current_format() {
    let path = temp_path("v2.tvim");
    let bit_width = 2;
    let dim = 16;
    let n_vectors = 4;
    let packed = vec![0x55u8; (dim / 8) * bit_width * n_vectors];
