        f.write_all(&vec![0u8; (32 / 8) * 4]).unwrap(); // packed codes
        f.write_all(&(1.0f32).to_le_bytes()).unwrap(); // norm
        f.write_all(&(42u64).to_le_bytes()).unwrap(); // id
    }

