//! Correctness tests for the rotation matrix generator.
//!
//! The rotation is a deterministic orthogonal matrix derived from a
//! fixed crate-wide seed via QR decomposition. These tests verify the
//! mathematical invariants the downstream quantizer depends on:
//!
//! - The matrix is orthogonal: `R^T R = I`.
//! - Rotation preserves vector L2 norms.
//! - Generation is deterministic across calls.
//! - `R^T` recovers the input (round-trip via the transpose).
//!
//! Tolerances here are generous enough for f32 + faer QR roundoff.

use turbovec::rotation::make_rotation_matrix;

fn mat_mul(a: &[f32], b: &[f32], dim: usize) -> Vec<f32> {
    let mut out = vec![0.0f32; dim * dim];
    for i in 0..dim {
        for j in 0..dim {
            let mut acc = 0.0f32;
            for k in 0..dim {
                acc += a[i * dim + k] * b[k * dim + j];
            }
            out[i * dim + j] = acc;
        }
    }
    out
}

fn transpose(m: &[f32], dim: usize) -> Vec<f32> {
    let mut t = vec![0.0f32; dim * dim];
    for i in 0..dim {
        for j in 0..dim {
            t[j * dim + i] = m[i * dim + j];
        }
    }
    t
}

fn mat_vec(m: &[f32], v: &[f32], dim: usize) -> Vec<f32> {
    let mut out = vec![0.0f32; dim];
    for i in 0..dim {
        let mut acc = 0.0f32;
        for j in 0..dim {
            acc += m[i * dim + j] * v[j];
        }
        out[i] = acc;
    }
    out
}

fn l2_norm(v: &[f32]) -> f32 {
    v.iter().map(|x| x * x).sum::<f32>().sqrt()
}

fn rand_vec(dim: usize, seed: u64) -> Vec<f32> {
    let mut state = seed.wrapping_mul(0x9E3779B97F4A7C15);
    let mut out = Vec::with_capacity(dim);
    for _ in 0..dim {
        state = state
            .wrapping_mul(6364136223846793005)
            .wrapping_add(1442695040888963407);
        let bits = (((state >> 32) as u32) & 0x007FFFFF) | 0x3F800000;
        let uniform = f32::from_bits(bits) - 1.0;
        out.push(uniform * 2.0 - 1.0);
    }
    out
}

#[test]
fn orthogonal_across_dims() {
    for &dim in &[32usize, 64, 128, 256] {
        let r = make_rotation_matrix(dim);
        let rt = transpose(&r, dim);
        let product = mat_mul(&rt, &r, dim);
        for i in 0..dim {
            for j in 0..dim {
                let expected = if i == j { 1.0 } else { 0.0 };
                let got = product[i * dim + j];
                assert!(
                    (got - expected).abs() < 1e-3,
                    "R^T R[{}][{}] = {}, expected {} (dim={})",
                    i,
                    j,
                    got,
                    expected,
                    dim
                );
            }
        }
    }
}

#[test]
fn preserves_norm() {
    for &dim in &[32usize, 64, 128] {
        let r = make_rotation_matrix(dim);
        for seed in 0..5u64 {
            let x = rand_vec(dim, seed);
            let y = mat_vec(&r, &x, dim);
            let nx = l2_norm(&x);
            let ny = l2_norm(&y);
            assert!(
                (nx - ny).abs() / nx < 1e-3,
                "norm changed: |Rx|={} vs |x|={} (dim={}, seed={})",
                ny,
                nx,
                dim,
                seed
            );
        }
    }
}

#[test]
fn deterministic_for_same_dim() {
    let r1 = make_rotation_matrix(128);
    let r2 = make_rotation_matrix(128);
    assert_eq!(r1.len(), r2.len());
    for (i, (a, b)) in r1.iter().zip(r2.iter()).enumerate() {
        assert_eq!(
            a.to_bits(),
            b.to_bits(),
            "rotation[{}] differs across calls: {} vs {}",
            i,
            a,
            b
        );
    }
}

#[test]
fn inverse_round_trip_via_transpose() {
    let dim = 128;
    let r = make_rotation_matrix(dim);
    let rt = transpose(&r, dim);
    for seed in 0..5u64 {
        let x = rand_vec(dim, seed);
        let rx = mat_vec(&r, &x, dim);
        let x_hat = mat_vec(&rt, &rx, dim);
        for (j, (orig, back)) in x.iter().zip(x_hat.iter()).enumerate() {
            assert!(
                (orig - back).abs() < 1e-3,
                "R^T R x [{}] = {} vs original {} (seed={})",
                j,
                back,
                orig,
                seed
            );
        }
    }
}

#[test]
fn size_matches_dim_squared() {
    for &dim in &[16usize, 64, 256] {
        let r = make_rotation_matrix(dim);
        assert_eq!(r.len(), dim * dim);
    }
}

//! Tests for lazy index construction on `TurboQuantIndex` and `IdMapIndex`.
//!
//! Invariants exercised:
//!   - `new_lazy(bit_width)` constructs an index with no committed dim.
//!   - `dim_opt()` returns `None` before the first add and `Some(d)` after.
//!   - `dim()` returns `0` as a sentinel before the first add.
//!   - `add_2d` / `add_with_ids_2d` lock the dim on first call and require
//!     a matching dim on subsequent calls.
//!   - `search` on a lazy uncommitted index returns empty results (no panic).
//!   - `prepare` on a lazy uncommitted index is a no-op.
//!   - `add` (the dim-implicit form) panics on a lazy uncommitted index.
//!   - File format: `write` from a lazy uncommitted index produces a file
//!     that loads back into a lazy uncommitted state; `write` from a
//!     committed index round-trips exactly.

use std::fs;
use turbovec::{IdMapIndex, TurboQuantIndex};

const DIM: usize = 64;

fn unit_vectors(n: usize, dim: usize, seed: u64) -> Vec<f32> {
    let mut state = seed | 1;
    let mut next = || {
        state ^= state << 13;
        state ^= state >> 7;
        state ^= state << 17;
        state
    };
    let mut uniform = || {
        let raw = (next() >> 40) as u32 | 1;
        raw as f32 / (1u32 << 24) as f32
    };
    let two_pi = 2.0_f32 * std::f32::consts::PI;
    let mut data = vec![0.0f32; n * dim];
    let mut i = 0;
    while i < data.len() {
        let u1 = uniform().max(1e-7);
        let u2 = uniform();
        let r = (-2.0 * u1.ln()).sqrt();
        let theta = two_pi * u2;
        data[i] = r * theta.cos();
        if i + 1 < data.len() {
            data[i + 1] = r * theta.sin();
        }
        i += 2;
    }
    for row in 0..n {
        let row_slice = &mut data[row * dim..(row + 1) * dim];
        let norm: f32 = row_slice.iter().map(|x| x * x).sum::<f32>().sqrt();
        if norm > 0.0 {
            let inv = 1.0 / norm;
            for x in row_slice.iter_mut() {
                *x *= inv;
            }
        }
    }
    data
}

// ---- TurboQuantIndex ----

#[test]
fn new_lazy_starts_with_no_dim() {
    let idx = TurboQuantIndex::new_lazy(4).unwrap();
    assert_eq!(idx.dim_opt(), None);
    assert_eq!(idx.dim(), 0, "dim() returns 0 as sentinel");
    assert_eq!(idx.len(), 0);
    assert_eq!(idx.bit_width(), 4);
}

#[test]
fn add_2d_locks_dim_on_first_call() {
    let mut idx = TurboQuantIndex::new_lazy(4).unwrap();
    let data = unit_vectors(3, DIM, 0xA00D_0001);
    idx.add_2d(&data, DIM).unwrap();
    assert_eq!(idx.dim_opt(), Some(DIM));
    assert_eq!(idx.len(), 3);
}

#[test]
fn add_2d_subsequent_calls_must_match_dim() {
    let mut idx = TurboQuantIndex::new_lazy(4).unwrap();
    let data1 = unit_vectors(2, DIM, 0xA00D_0002);
    idx.add_2d(&data1, DIM).unwrap();
    let data2 = unit_vectors(2, DIM, 0xA00D_0003);
    idx.add_2d(&data2, DIM).unwrap();
    assert_eq!(idx.len(), 4);
}

#[test]
fn add_2d_rejects_dim_change() {
    let mut idx = TurboQuantIndex::new_lazy(4).unwrap();
    let data = unit_vectors(1, DIM, 0xA00D_0004);
    idx.add_2d(&data, DIM).unwrap();
    let wrong = unit_vectors(1, DIM * 2, 0xA00D_0005);
    let err = idx.add_2d(&wrong, DIM * 2).err().unwrap();
    assert_eq!(
        err,
        turbovec::AddError::DimMismatch {
            existing: DIM,
            got: DIM * 2,
        },
    );
}

#[test]
#[should_panic(expected = "dim is not set")]
fn plain_add_panics_on_lazy_uncommitted() {
    let mut idx = TurboQuantIndex::new_lazy(4).unwrap();
    let data = unit_vectors(1, DIM, 0xA00D_0006);
    idx.add(&data);
}

#[test]
fn search_on_lazy_uncommitted_returns_empty() {
    let idx = TurboQuantIndex::new_lazy(4).unwrap();
    let queries = unit_vectors(2, DIM, 0xA00D_0007);
    let res = idx.search(&queries, 5);
    assert_eq!(res.scores.len(), 0);
    assert_eq!(res.indices.len(), 0);
    assert_eq!(res.k, 0);
}

#[test]
fn prepare_on_lazy_uncommitted_is_noop() {
    let idx = TurboQuantIndex::new_lazy(4).unwrap();
    idx.prepare(); // should not panic
}

#[test]
fn write_load_round_trip_lazy_uncommitted() {
    let tmp = std::env::temp_dir().join("turbovec_lazy_uncommitted.tv");
    {
        let idx = TurboQuantIndex::new_lazy(4).unwrap();
